// Starter outfits are granted once by ID when loading either a new or existing profile.
const STARTER_OUTFITS=[
 {id:'starter-mint',name:'薄荷心情 · 头像框',type:'frame',color:'mint',symbol:'✦'},
 {id:'starter-sky',name:'晴空来信 · 头像框',type:'frame',color:'lilac',symbol:'☁'},
 {id:'starter-blossom',name:'樱花笔记 · 头像框',type:'frame',color:'peach',symbol:'✿'},
 {id:'starter-dawn',name:'晨光校园 · 主页背景',type:'background',color:'sunset',symbol:'◒'},
 {id:'starter-notebook',name:'方格手账 · 主页背景',type:'background',color:'lilac',symbol:'▦'},
 {id:'starter-lake',name:'湖畔午后 · 主页背景',type:'background',color:'mint',symbol:'≈'}
].map(p=>({...p,starter:true,brand:'CAMPUS WELCOME',category:'免费装扮',cost:0,stock:999,detail:'默认拥有，无需购买、兑换或连接钱包。'}));
function profileCoverClass(id=social.background){return ({starlight:'star-cover','starter-dawn':'cover-dawn','starter-notebook':'cover-notebook','starter-lake':'cover-lake'})[id]||'';}
function outfitCard(p){const worn=(social.equipped===p.id&&!window.campusNFT?.frame())||social.background===p.id;return `<article class="outfit-card ${worn?'outfit-worn':''}"><div class="outfit-preview ${p.type==='background'?'outfit-cover '+profileCoverClass(p.id):'outfit-avatar '+p.color}">${p.type==='frame'?`<span class="social-avatar large lilac frame-${p.id}">K</span>`:'<span class="preview-cover-title">MY CAMPUS,<br>MY STORY.</span>'}<span class="outfit-kind">${p.type==='frame'?'头像框':'主页背景'}</span></div><div class="outfit-info"><span class="outfit-source">${p.starter?'默认拥有 · 免费':p.eventOnly?'活动限定':'积分兑换'}</span><h3>${p.name}</h3><button class="${worn?'outline':'primary'} full" data-equip="${p.id}" ${worn?'disabled':''}>${worn?'✓ 正在使用':p.type==='frame'?'使用头像框':'使用此背景'}</button></div></article>`;}
function wardrobeView(){const available=social.owned.map(id=>products.find(p=>p.id===id)).filter(p=>p&&['frame','background'].includes(p.type));const groups=[['每个人都有的第一份风格','6 件免费装扮，无需购买或领取，随时自由搭配。',available.filter(p=>p.starter)],['用参与收藏的特别回忆','活动奖励与积分兑换的装扮，也收纳在这里。',available.filter(p=>!p.starter)]];return `<section class="wardrobe-current"><div class="wardrobe-current-avatar">${avatar('me',true)}</div><div><span class="eyebrow">MAKE IT YOURS</span><h3>今天，想用哪一种风格？</h3><p>${escapeHTML(window.campusNFT?.frame()?'光迹摄影 · 链上 NFT 头像框':products.find(p=>p.id===social.equipped)?.name||'默认头像')}<span> / </span>${escapeHTML(products.find(p=>p.id===social.background)?.name||'默认主页背景')}</p></div><button class="outline" data-reset-dress>恢复默认</button></section>${groups.filter(g=>g[2].length).map(([title,description,items])=>`<section class="wardrobe-group"><div class="section-head"><div><h2>${title}</h2><p>${description}</p></div><span class="wardrobe-total">${items.length} 件</span></div><div class="outfit-grid">${items.map(outfitCard).join('')}</div></section>`).join('')}${window.campusNFT?.wardrobe()||''}<div class="wardrobe-note"><p>头像框同步展示在名片、动态和评论中；背景展示在个人主页。当前选择会在此浏览器保存。</p><button class="text-button" data-nav="shop">去商城发现更多装扮</button></div>`;}
